package br.com.confirmacao.user.api;import br.com.confirmacao.user.domain.*;import java.time.Instant;import java.util.UUID;public record UserResponse(UUID id,UUID professionalId,String name,String email,UserRole role,boolean active,Instant createdAt,Instant updatedAt){public static UserResponse from(User u){return new UserResponse(u.getId(),u.getProfessional()==null?null:u.getProfessional().getId(),u.getName(),u.getEmail(),u.getRole(),u.isActive(),u.getCreatedAt(),u.getUpdatedAt());}}
